import{z as o,x as l,o as t,c as d,q as s,j as n,D as e,d as a,s as i,S as A,b as B}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"组合压力测试","description":"","frontmatter":{"title":"组合压力测试","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/pf-stress-testing.md","filePath":"quant/pf-stress-testing.md","lastUpdated":1791063341000}'),p={name:"quant/pf-stress-testing.md"};function u(f,E,h,F,C,m){const r=l("Mermaid");return t(),d("div",null,[E[2]||(E[2]=s('<h1 id="组合压力测试" tabindex="-1">组合压力测试 <a class="header-anchor" href="#组合压力测试" aria-label="Permalink to &quot;组合压力测试&quot;">​</a></h1><div class="epigraph"><p>VaR 告诉你在正常的日子里会丢多少；压力测试告诉你，你的组合在哪个故事里死掉——以及那个故事是不是早已写在你的持仓里。</p><footer>—— 据 Basel Committee on Banking Supervision, Principles for Sound Stress Testing Practices and Supervision, 2009（2018 年修订）整理</footer></div><p><a href="/quant/pf-tail-hedging">上一课</a>把尾部预算写进组合，验收的三道里留了一道「情景库打分」。本课把情景库这一层写全：压力测试是组合的反事实体检，从 <a href="/quant/var-methods">VaR：历史、参数、MC</a> 的正常日推进到故事的极端日。机构侧的条目已有——<a href="/quant/stressed-var-frtb">压力 VaR 与 FRTB</a>、<a href="/quant/reverse-stress-test">反向压力测试</a>、<a href="/quant/liquidity-adjusted-var">流动性调整 VaR</a>；本课写组合管理者视角：设计、传导、行动、复检。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>压力测试最容易退化成合规仪式。典型死法：情景只用历史重放，而资产名单早已换代——重放 2008 对今天的组合是错位的考题；冲击只打到一阶资产价格，不打因子与相关——而危机的第一特征恰是<a href="/quant/correlation-breakdown">相关性崩溃</a>：分散化假设在最需要它的一天集体失效。<span class="marginnote">「相关性崩溃」就是平时各走各的资产，在危机里突然同涨同跌。直觉类比：晴天时各人有各人的行程，互不挡路；火灾时所有人冲向同一个出口——平时算好的「分散化」，恰恰在最需要的那天集体失灵。</span>只测市场风险，不测流动性与资金——<a href="/quant/liquidity-adjusted-var">流动性调整 VaR</a> 的平仓成本与<a href="/quant/futures-margin">期货保证金</a>的追缴时间表才是压力里真正的死亡路径；最后一条：测完不接行动，报告归档、仓位照旧，压力测试变成一年一度的自欺。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把压力测试装成一条有工序的流水线：先建情景库，再把情景送进分层传导引擎，最后把输出钉到预承诺的行动与 owner 上。三段各有各的死法，也各有各的验收：情景看来源与覆盖度，传导看因子、相关与二阶效应，行动看有没有复检日期与去向。下面按这条工序走一遍。</p><h3 id="情景、传导、行动" tabindex="-1">情景、传导、行动 <a class="header-anchor" href="#情景、传导、行动" aria-label="Permalink to &quot;情景、传导、行动&quot;">​</a></h3><p>情景三族：历史重放（2008、2020、2022，按当年路径而非单日快照）；假设宏观（滞胀、利率跳升三百基点、信用利差翻倍、股票波动翻倍同时相关趋一）；组合特异——用<a href="/quant/reverse-stress-test">反向压力测试</a>的口径反解：让本组合亏损超过容忍线的最小冲击集是什么，那个集子里的方向就是组合真正的隐藏集中度。<span class="marginnote">反向压力测试就是倒着做题：不问「这个情景亏多少」，而问「要亏穿容忍线，最少需要哪些冲击同时发生」。类比：保险公司不满足于计算已知灾种，还要反推「怎样一场灾难能让公司破产」——那个答案暴露的正是最该盯住的敞口。</span>传导分层：资产冲击之上打因子冲击——用本课程前面的因子语言与协方差机器重算各因子的贡献；相关矩阵按压力体制重估（<a href="/quant/copula-var">Copula VaR</a> 的工具箱在此）；再往下是二阶效应：追加保证金、赎回压力、被迫去杠杆的螺旋（<a href="/quant/liquidity-spiral-risk">流动性螺旋风险</a>），以及上一课的现金流时序——对冲赔付与保证金追缴是否撞在同一天。行动闭环：每个情景有 owner、有预承诺的触发行动（减哪些仓、动用哪条授信、对冲腿加多少）、有复检日期；结果进限额体系，不进抽屉。</p>',9)),(t(),n(A,null,{default:e(()=>[i(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LIB%5B%22%E6%83%85%E6%99%AF%E5%BA%93%EF%BC%9A%E5%8E%86%E5%8F%B2%2F%E5%81%87%E8%AE%BE%2F%E5%8F%8D%E5%90%91%22%5D%20--%3E%20ENG%5B%22%E4%BC%A0%E5%AF%BC%E5%BC%95%E6%93%8E%EF%BC%9A%E8%B5%84%E4%BA%A7%E5%88%B0%E5%9B%A0%E5%AD%90%E5%88%B0%E7%9B%B8%E5%85%B3%22%5D%0A%20%20ENG%20--%3E%20SECOND%5B%22%E4%BA%8C%E9%98%B6%EF%BC%9A%E4%BF%9D%E8%AF%81%E9%87%91%E3%80%81%E8%B5%8E%E5%9B%9E%E3%80%81%E5%8E%BB%E6%9D%A0%E6%9D%86%E8%9E%BA%E6%97%8B%22%5D%0A%20%20SECOND%20--%3E%20LIQ%5B%22%E6%B5%81%E5%8A%A8%E6%80%A7%E7%BB%B4%E5%BA%A6%EF%BC%9A%E5%A4%9A%E9%95%BF%E6%97%B6%E9%97%B4%E8%83%BD%E5%B9%B3%E5%A4%9A%E5%B0%91%E4%BB%93%22%5D%0A%20%20LIQ%20--%3E%20ACT%5B%22%E8%A1%8C%E5%8A%A8%E6%98%A0%E5%B0%84%EF%BC%9A%E9%A2%84%E6%89%BF%E8%AF%BA%E7%9A%84%E8%A7%A6%E5%8F%91%E4%B8%8E%20owner%22%5D%0A%20%20ACT%20--%3E%20REVIEW%5B%22%E5%A4%8D%E6%A3%80%E4%B8%8E%E9%99%90%E9%A2%9D%E6%9B%B4%E6%96%B0%22%5D%0A%20%20REVIEW%20--%3E%7C%E6%96%B0%E4%BF%A1%E6%81%AF%E5%9B%9E%E6%B5%81%7C%20LIB%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("压力测试与 VaR 为什么互补而非重复：VaR 用样本期内的分布高分位说话，样本外没有承诺；压力测试显式引入样本里没有的故事，本质是把「分布之外」变成可讨论的对象。"),B("a",{href:"/quant/var-backtest"},"回测 VaR：Kupiec / Christoffersen"),a(" 管 VaR 的违约率，压力测试没有真值可回测——所以它的质量标准不是统计显著性，而是情景的现实性、覆盖度与行动接续，这正是它容易被做成形式的原因：形式化的成本极低，收益却要等到危机日才结算。巴塞尔委员会 2009 年金融危机后的检讨把这条写成原则：压力测试应当独立于 VaR 的假设、贯穿全机构、且结果必须映射到可执行的风险缓释。对组合管理者的版本更朴素：每年至少一条情景必须来自组合存续期之外的历史，每条情景必须能回答「明天早上我们做什么」。")],-1)),(t(),n(A,null,{default:e(()=>[i(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20TOL%5B%22%E8%AE%BE%E4%BA%8F%E6%8D%9F%E5%AE%B9%E5%BF%8D%E7%BA%BF%EF%BC%8C%E4%BE%8B%E5%A6%82%E4%B8%80%E5%B9%B4%E4%BA%8F%2020%25%22%5D%20--%3E%20SEARCH%5B%22%E5%8F%8D%E8%A7%A3%EF%BC%9A%E6%90%9C%E5%AF%BB%E6%9C%80%E5%B0%8F%E5%86%B2%E5%87%BB%E9%9B%86%22%5D%0A%20%20SEARCH%20--%3E%20S1%5B%22%E5%80%99%E9%80%89%E5%86%B2%E5%87%BB%E4%B8%80%EF%BC%9A%E5%88%A9%E7%8E%87%E8%B7%B3%E5%8D%87%E4%B8%89%E7%99%BE%E5%9F%BA%E7%82%B9%22%5D%0A%20%20SEARCH%20--%3E%20S2%5B%22%E5%80%99%E9%80%89%E5%86%B2%E5%87%BB%E4%BA%8C%EF%BC%9A%E4%BF%A1%E7%94%A8%E5%88%A9%E5%B7%AE%E7%BF%BB%E5%80%8D%E5%8A%A0%E7%9B%B8%E5%85%B3%E8%B6%8B%E4%B8%80%22%5D%0A%20%20SEARCH%20--%3E%20S3%5B%22%E5%80%99%E9%80%89%E5%86%B2%E5%87%BB%E4%B8%89%EF%BC%9A%E5%95%86%E5%93%81%E6%B1%87%E7%8E%87%E5%90%8C%E5%90%91%E8%B7%B3%22%5D%0A%20%20S1%20--%3E%20HIT%5B%22%E6%81%B0%E5%A5%BD%E5%87%BB%E7%A9%BF%E5%AE%B9%E5%BF%8D%E7%BA%BF%E7%9A%84%E6%9C%80%E5%B0%8F%E7%BB%84%E5%90%88%22%5D%0A%20%20S2%20--%3E%20HIT%0A%20%20S3%20--%3E%20HIT%0A%20%20HIT%20--%3E%20DISC%5B%22%E8%BF%99%E4%BA%9B%E6%96%B9%E5%90%91%E5%B0%B1%E6%98%AF%E7%BB%84%E5%90%88%E7%9A%84%E9%9A%90%E8%97%8F%E9%9B%86%E4%B8%AD%E5%BA%A6%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=s('<p><span class="marginnote">常见误区：以为压力测试过关等于「扛得住」。一阶亏损过关了，二阶账单可能才到：亏 10% 触发赎回，为付赎回被迫卖流动性最好的资产，价格再跌、赎回更多——死亡螺旋通常不是从亏损本身开始，而是从「为付钱而卖」开始。</span></p><p><span class="marginnote">监管的先例可借：FRTB 的压力 VaR 用固定的危机窗口重校波动与相关，等于把「最坏时期」钉进资本要求——组合侧的对应物，是把至少一条固定危机情景写进每次调仓的预检，而不是临时起意。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写银行监管资本的计量细节（<a href="/quant/stressed-var-frtb">压力 VaR 与 FRTB</a>），不展开限额体系与资本配置（风险体系深化课程的对象）。压力测试的输出有三个去向：对冲预算的输入（上一课）、限额的输入、以及估值与流动性假设的输入；做成独立报告是它最常见的死法。情景的现实性没有上限检验——过于离谱的情景会消耗组织注意力，过近的情景又只覆盖上一个危机；这个权衡靠制度化的情景评审而不是靠算力。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>情景三族：历史重放、假设宏观、反向压力测试；反向那条找出的是组合真正的隐藏集中度。</li><li>传导要分层：资产、因子、相关、二阶效应（保证金、赎回、螺旋），并带时钟。</li><li>压力测试没有可回测的真值，质量标准是现实性、覆盖度与行动接续。</li><li>每条情景要有 owner 与预承诺行动；测完不改仓位的压力测试是仪式。</li><li>出处：Basel Committee on Banking Supervision, Principles for Sound Stress Testing Practices and Supervision, 2009（2018 修订）。</li></ul>',6))])}const q=o(p,[["render",u]]);export{c as __pageData,q as default};
